using System.Text.Json;using System.Text.RegularExpressions;using System.Text;
namespace GameTranslator.Translation;
/// <summary>A bounded, local snapshot of known log fields; no settings, keys or network access.</summary>
public static class ComparisonLogExporter {
 public sealed record Result(int Rows,int Skipped);
 private static string Safe(string? value,int max){value??="";value=Regex.Replace(value,@"AIza[A-Za-z0-9_-]{25,}|sk-[A-Za-z0-9_-]{20,}|(?:ghp_|github_pat_)[A-Za-z0-9_]{15,}","[REDACTED]");return value[..Math.Min(max,value.Length)];}
 public static Result Export(string source,string destination){if(Path.GetFullPath(source).Equals(Path.GetFullPath(destination),StringComparison.OrdinalIgnoreCase)||Path.GetFullPath(source+".previous").Equals(Path.GetFullPath(destination),StringComparison.OrdinalIgnoreCase))throw new ArgumentException("Choose another output file");int rows=0,skipped=0;string temp=destination+".tmp-"+Guid.NewGuid().ToString("N");try{using(var output=new StreamWriter(temp,false,new UTF8Encoding(false))){foreach(var path in new[]{source+".previous",source}){if(!File.Exists(path))continue;using var input=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete);long remaining=input.Length;if(remaining>12_000_000)throw new InvalidDataException("Log too large");using var snapshot=new MemoryStream();byte[] buffer=new byte[8192];while(remaining>0){int n=input.Read(buffer,0,(int)Math.Min(buffer.Length,remaining));if(n==0)break;snapshot.Write(buffer,0,n);remaining-=n;}snapshot.Position=0;using var reader=new StreamReader(snapshot);while(reader.ReadLine() is {} line){if(line.Length>32000){skipped++;continue;}try{var entry=JsonSerializer.Deserialize<ComparisonEntry>(line);if(entry==null||string.IsNullOrWhiteSpace(entry.English)||entry.Arabic==null){skipped++;continue;}var clean=entry with{Session=Safe(entry.Session,100),Game=Safe(entry.Game,200),Engine=Safe(entry.Engine,200),English=Safe(entry.English,2000),Arabic=Safe(entry.Arabic,3000),Method=Safe(entry.Method,200),Edition=Safe(entry.Edition,40),Console=Safe(entry.Console,40),OcrLanguage=Safe(entry.OcrLanguage,40),Error=Safe(entry.Error,100),AreaId=Safe(entry.AreaId,80),AreaName=Safe(entry.AreaName,100)};output.WriteLine(JsonSerializer.Serialize(clean));rows++;}catch(JsonException){skipped++;}}}}if(rows==0)throw new InvalidDataException("No recorded lines");File.Move(temp,destination,true);return new(rows,skipped);}finally{if(File.Exists(temp))File.Delete(temp);}}
}
